<script setup lang="ts">
/**
 * Slides shown one at a time, paged by the reader (`design/components/carousel.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/carousel.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  computed,
  onBeforeUnmount,
  onMounted,
  ref,
  useId,
  useTemplateRef,
  watch,
  type VNode,
} from 'vue'

import * as zag from '@zag-js/carousel'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { agentMember, useDirection } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/carousel.module.css'
import Button from '../controls/Button.vue'

export interface CarouselSlide {
  id: string
  label: string
  content: VNode | string
}

export interface CarouselProps {
  defaultIndex?: number
  /**
   * The current slide, controlled as in Slider; swiping also calls `onIndexChange`.
   */
  index?: number
  /**
   * Names the carousel, such as "Product tour" rather than "Carousel".
   */
  label: string
  /**
   * Wraps from the first slide to the last and back; when off, the end buttons are disabled.
   */
  loop?: boolean
  nextLabel: string
  /**
   * Accessible names for the previous and next buttons, in the app's language, with no default.
   */
  previousLabel: string
  /**
   * Spoken role names for the region and each slide (default `carousel` and `slide`, the APG's
   * terms); localized hosts pass both or neither.
   */
  roleDescriptions?: { carousel: string; slide: string }
  /**
   * Slides in reading order; an empty list renders nothing, and the page handles it.
   */
  slides: CarouselSlide[]
}

defineOptions({ name: 'Carousel', inheritAttrs: false })

const props = withDefaults(defineProps<CarouselProps>(), {
  defaultIndex: 0,
  loop: false,
  roleDescriptions: () => ({ carousel: 'carousel', slide: 'slide' }),
})
const emit = defineEmits<{ indexChange: [index: number] }>()
const uid = useId()
const kept = ref(props.index ?? props.defaultIndex)
const scrolls = ref(0)
const sent = ref(-1)
const moving = ref(false)
const controls = useTemplateRef<HTMLElement>('controls')
const root = useTemplateRef<HTMLElement>('root')
const viewport = useTemplateRef<HTMLElement>('viewport')
const measurable = computed(() => () => viewport.value !== null && viewport.value.clientWidth > 0)
const within = computed(
  () => (at: number) => Math.min(Math.max(at, 0), Math.max(props.slides.length - 1, 0)),
)
const shown = computed(() => within.value(props.index ?? kept.value))
const instant = computed(() => () => {
  const duration =
    viewport.value === null
      ? NaN
      : parseFloat(
          getComputedStyle(viewport.value).getPropertyValue('--pm-motion-duration-surface'),
        )
  return Number.isNaN(duration) || duration <= 0
})
const travel = computed(() => (to: number) => {
  if (to === shown.value) return
  if (props.index === undefined) go.value(to, instant.value())
  else emit('indexChange', to)
})
const resting = computed(
  () => (nearest: number) =>
    viewport.value !== null &&
    Math.abs(Math.abs(viewport.value.scrollLeft) - nearest * viewport.value.clientWidth) <= 1,
)
const documentDirection = useDirection(() => root.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    slideCount: props.slides.length,
    defaultPage: props.index ?? props.defaultIndex,
    loop: props.loop,
    onPageChange: (details) => {
      measurable.value() &&
        details.page !== kept.value &&
        ((kept.value = details.page),
        details.page !== props.index && emit('indexChange', details.page))
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const go = computed(() => (to: number, now: boolean) => {
  sent.value = scrolls.value
  moving.value = true
  api.value.scrollTo(to, now)
})
const settle = computed(() => () => {
  if (viewport.value === null || !measurable.value()) return
  const nearest = within.value(
    Math.round(Math.abs(viewport.value.scrollLeft) / viewport.value.clientWidth),
  )
  if (moving.value) {
    if (scrolls.value === sent.value || !resting.value(nearest)) return
    moving.value = false
  }
  if (nearest !== api.value.page) go.value(nearest, true)
})
const effect1 = () => {
  props.index !== undefined &&
    ((kept.value = within.value(props.index)),
    within.value(props.index) !== api.value.page &&
      go.value(within.value(props.index), instant.value()))
}
watch(() => props.index, effect1, { flush: 'post' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const run = () => {
    measurable.value() &&
      api.value.page !== within.value(kept.value) &&
      go.value(within.value(kept.value), true)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [viewport.value]) if (element) resize?.observe(element)
  release2 = () => {
    resize?.disconnect()
  }
  run()
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const timer = setTimeout(() => {
    settle.value()
  }, 150)
  release3 = () => clearTimeout(timer)
}
watch(() => scrolls.value, effect3, { flush: 'post' })
onBeforeUnmount(() => release3?.())
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const run = () => {
    viewport.value !== null &&
      viewport.value.getAttribute('tabindex') !== '0' &&
      viewport.value.setAttribute('tabindex', '0')
  }
  const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
  for (const element of [viewport.value])
    if (element)
      mutation?.observe(element, {
        childList: true,
        characterData: true,
        subtree: true,
        attributeFilter: ['tabindex'],
      })
  release4 = () => {
    mutation?.disconnect()
  }
  run()
}
onMounted(effect4)
onBeforeUnmount(() => release4?.())
let release5: (() => void) | undefined
const effect5 = () => {
  release5?.()
  const ran = agentMember({
    member: 'Carousel',
    element: () => root.value,
    state: () => ({
      index: shown.value,
      slides: props.slides.map((slide) => ({ id: slide.id, label: slide.label })),
    }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            if (!Number.isInteger(value) || value < 0 || value >= props.slides.length) {
              throw new Error(
                `There is no slide ${value}; the slides run from 0 to ${props.slides.length - 1}.`,
              )
            }
            travel.value(value)
          })(),
      },
    },
    withholds: () => controls.value,
  })
  release5 = () => {
    ran()
  }
}
onMounted(effect5)
onBeforeUnmount(() => release5?.())
</script>

<template>
  <section
    v-if="slides.length > 0"
    ref="root"
    role="group"
    :aria-roledescription="roleDescriptions.carousel"
    :aria-label="label"
    data-member="carousel"
  >
    <!-- viewport -->
    <div
      ref="viewport"
      v-bind="{ ...api.getItemGroupProps(), style: undefined, dir: undefined }"
      :class="styles.viewport"
      tabindex="0"
      role="region"
      :aria-label="label"
      :aria-live="undefined"
      @scroll="scrolls += 1"
    >
      <template v-for="(slide, at) in slides" :key="slide.id">
        <!-- slide -->
        <div
          v-bind="{ ...api.getItemProps({ index: at }), style: undefined, dir: undefined }"
          :class="styles.slide"
          role="group"
          :aria-roledescription="roleDescriptions.slide"
          :aria-label="slide.label"
          :aria-hidden="undefined"
        >
          <template v-if="typeof slide.content === 'string'">{{ slide.content }}</template>
          <template v-else>
            <component :is="slide.content" />
          </template>
        </div>
      </template>
    </div>
    <!-- controls -->
    <div ref="controls" :class="styles.controls">
      <Button
        variant="ghost"
        tone="neutral"
        size="sm"
        :iconOnly="true"
        icon="previous"
        :label="previousLabel"
        :disabled="!loop && shown === 0"
        @click="travel(shown === 0 ? slides.length - 1 : shown - 1)"
      />
      <!-- rail -->
      <span :class="styles.rail">
        <template v-for="(slide, at) in slides" :key="slide.id">
          <!-- dot -->
          <button
            :class="styles.dot"
            type="button"
            data-carousel-part="dot"
            :aria-label="slide.label"
            :aria-current="at === shown ? true : undefined"
            @click="travel(at)"
          />
        </template>
      </span>
      <Button
        variant="ghost"
        tone="neutral"
        size="sm"
        :iconOnly="true"
        icon="next"
        :label="nextLabel"
        :disabled="!loop && shown === slides.length - 1"
        @click="travel(shown === slides.length - 1 ? 0 : shown + 1)"
      />
    </div>
  </section>
</template>
